with base as (select id, store_name, city, region, opened_date, initcap(trim(region)) as region_title from stores where opened_date >= date '2023-09-24') select city, region, size(collect_set(region)) as num_regions, sort_array(collect_set(region)) as region_list, count(case when region = 'Central' then 1 end) as central_count, sort_array(collect_set(city)) as city_list, count(distinct city) as distinct_cities, count(case when city = 'Chiang Mai' then 1 end) as chiang_mai_count, percent_rank() over (partition by city order by count(case when region = 'Central' then 1 end) desc) as central_count_percent_rank from base group by city, region;
